steps.script:
var main = tree.current_scene
var H = load("res://tests/helpers/sm11e_m3a_scen.gd")
return H.setup(2, {"cp": {"1": 0}})

var army: Dictionary = ArmyListManager.load_army_list("sm11e_codex_test", 2)
if not army.get("units", {}).has("U_CAPTAIN_IN_PHOBOS_ARMOUR_A"):
	return "no Captain in Phobos Armour in sm11e_codex_test"
if GameState.state.units.has("U_CAPTAIN_IN_PHOBOS_ARMOUR_A"):
	return "fixture already has the Captain"
var cap: Dictionary = army.units["U_CAPTAIN_IN_PHOBOS_ARMOUR_A"].duplicate(true)
cap["id"] = "U_CAPTAIN_IN_PHOBOS_ARMOUR_A"
cap["owner"] = 2
cap["status"] = 2
cap["flags"] = {}
cap["attachment_data"] = {"attached_characters": []}
cap.erase("attached_to")
cap.erase("embarked_in")
var front = null
for m in GameState.state.units["U_KOMMANDOS_A"].models:
	if m.get("alive", true) and (front == null or float(m.position.y) > float(front.position.y)):
		front = m
cap.models[0]["position"] = {"x": float(front.position.x), "y": float(front.position.y) + 76.0}
cap.models[0]["alive"] = true
GameState.state.units["U_CAPTAIN_IN_PHOBOS_ARMOUR_A"] = cap
tree.current_scene._recreate_unit_visuals()
GameState.state.meta["ea63_cap_y0"] = float(cap.models[0].position.y)
var C = load("res://scripts/codex/space_wolves/SWCommon.gd")
return str(C.engaged_enemy_ids("U_CAPTAIN_IN_PHOBOS_ARMOUR_A"))

var main = tree.current_scene
var H = load("res://tests/helpers/sm11e_m3a_scen.gd")
var p = GameState.get_unit("U_CAPTAIN_IN_PHOBOS_ARMOUR_A").models[0].position
return H.frame(float(p.x) / 40.0, float(p.y) / 40.0 + 3.0, 1.3)

var main = tree.current_scene
var H = load("res://tests/helpers/sm11e_m3a_scen.gd")
var fp = H.phase()
for uid in GameState.state.units:
	if fp.sequencer_11e.eligible_to_fight(uid, GameState.state):
		fp.sequencer_11e.mark_fought(uid, GameState.state)
return fp.get_end_fight_status().step_over

var main = tree.current_scene
var H = load("res://tests/helpers/sm11e_m3a_scen.gd")
var d = tree.current_scene._phase_end_confirm
if d != null and d.visible:
	d.get_ok_button().pressed.emit()
return true

var main = tree.current_scene
var H = load("res://tests/helpers/sm11e_m3a_scen.gd")
return H.window_id()

var main = tree.current_scene
var H = load("res://tests/helpers/sm11e_m3a_scen.gd")
return H.decider()

var u = GameState.get_unit("U_CAPTAIN_IN_PHOBOS_ARMOUR_A")
var dy: float = float(u.models[0].position.y) - float(GameState.state.meta["ea63_cap_y0"])
print("[ea63] Captain moved %.2f in, engaged=%s" % [dy / 40.0, str(RulesEngine.is_unit_engaged("U_CAPTAIN_IN_PHOBOS_ARMOUR_A", GameState.state))])
return dy > 40.0 and not RulesEngine.is_unit_engaged("U_CAPTAIN_IN_PHOBOS_ARMOUR_A", GameState.state)
